void DaxaDepthPipeline::validate_pair(const DaxaFrame& pre,const DaxaStereo::Frame& left,const DaxaStereo::Frame& right){auto calibration=pre.calibration();require(calibration&&left.calibration_owner()==calibration&&right.calibration_owner()==calibration,"depth exact calibration owner mismatch");require(left.reference()==DaxaStereoReference::Left&&right.reference()==DaxaStereoReference::Right,"depth requires true Left/Right references");require(pre.context_id()==left.context_id()&&pre.context_id()==right.context_id(),"depth source pair context mismatch");auto source=pre.source();require(source&&source==left.source()&&source==right.source(),"depth source pair mismatch");require(left.calibration_identity()==calibration->rectified_identity&&right.calibration_identity()==calibration->rectified_identity,"depth calibrated source pair mismatch");require(source->frame_id<=uint64_t(INT64_MAX),"source ID exceeds signed64 observation domain");}
DaxaDepthPipeline::DaxaDepthPipeline(DaxaRectification c,DaxaDepthConfig config,std::shared_ptr<DaxaFoundation> context,CaptureLease prototype):impl_(std::make_shared<Impl>(std::move(c),config,std::move(context),std::move(prototype))){}
DaxaDepthPipeline::DaxaDepthPipeline(DaxaDepthConfig config,std::shared_ptr<DaxaFoundation> context,const DaxaFrame& prototype):impl_(std::make_shared<Impl>(config,std::move(context),prototype)){}
DaxaDepthPipeline::Frame::Frame(std::shared_ptr<Impl> owner,std::shared_ptr<Slot> slot):owner_(std::move(owner)),slot_(std::move(slot)),generation_(slot_->generation){}
DaxaDepthPipeline::Frame& DaxaDepthPipeline::Frame::operator=(Frame other)noexcept{owner_.swap(other.owner_);slot_.swap(other.slot_);std::swap(generation_,other.generation_);return *this;}
void DaxaDepthPipeline::Frame::validate()const{require(owner_&&slot_&&generation_==slot_->generation&&slot_->preprocessing,"empty/stale depth frame");}
