size_t DaxaDepthPipeline::collect(){impl_->require_thread();return impl_->collect_at(impl_->context->device.oldest_pending_submit_index());}
void DaxaDepthPipeline::drain(){impl_->require_thread();impl_->context->device.wait_idle();collect();impl_->context->device.collect_garbage();}
DaxaObservationFrame DaxaDepthPipeline::Frame::observations()const{
    validate();std::array<daxa::BufferId,6> planes{};for(unsigned i=0;i<6;++i)planes[i]=slot_->outputs[i+3];
    std::array<DaxaObservationImageView,4> images{};auto maps=slot_->preprocessing.calibration();
    for(unsigned i=0;i<4;++i)images[i]=DaxaObservationImageView(slot_->preprocessing.plane(DaxaPreprocessPlane(i)).buffer(),i<2?maps->eye_width:maps->width,i<2?maps->source_height:maps->height);
    return DaxaObservationFrame(owner_->context,owner_,slot_,&slot_->generation,generation_,slot_->submit,std::move(maps),slot_->preprocessing.source(),planes,images);
}
void DaxaDepthPipeline::Frame::wait()const{validate();owner_->context->device.wait_on_submit({.queue=daxa::QUEUE_MAIN,.queue_submit_index=slot_->submit,.timeout=30'000'000'000ull});}
bool DaxaDepthPipeline::Frame::ready()const{validate();return detail::completed_submission(slot_->submit,owner_->context->device.oldest_pending_submit_index());}
uint32_t DaxaDepthPipeline::Frame::width()const{validate();return owner_->config.stereo.width;}uint32_t DaxaDepthPipeline::Frame::height()const{validate();return owner_->config.stereo.height;}uint64_t DaxaDepthPipeline::Frame::generation()const{validate();return generation_;}uint64_t DaxaDepthPipeline::Frame::context_id()const{validate();return reinterpret_cast<uintptr_t>(owner_->context->device.get());}
daxa::BufferId DaxaDepthPipeline::Frame::buffer(DaxaDepthPlane p)const{validate();require(unsigned(p)<9,"invalid depth plane");return slot_->outputs[unsigned(p)];}size_t DaxaDepthPipeline::Frame::size_bytes(DaxaDepthPlane p)const{validate();require(unsigned(p)<9,"invalid depth plane");return size_t(width())*height()*2*element_bytes[unsigned(p)];}
DaxaImageView DaxaDepthPipeline::Frame::image(DaxaPreprocessPlane p)const{validate();return slot_->preprocessing.plane(p);}CaptureLease DaxaDepthPipeline::Frame::source()const{validate();return slot_->preprocessing.source();}std::shared_ptr<const DaxaRectification> DaxaDepthPipeline::Frame::calibration()const{validate();return slot_->preprocessing.calibration();}MetricCalibration DaxaDepthPipeline::Frame::metric_calibration()const{validate();return owner_->metric;}
DaxaRightReferenceMode DaxaDepthPipeline::Frame::right_reference_mode()const{validate();return owner_->config.right_reference_mode;}
DaxaLRDependency DaxaDepthPipeline::Frame::lr_dependency()const{validate();return right_reference_mode()==DaxaRightReferenceMode::LeftAggregatedSelection?DaxaLRDependency::LeftAggregatedCorrelated:DaxaLRDependency::IndependentReferences;}
DaxaStereo::Frame DaxaDepthPipeline::Frame::stereo_frame(DaxaStereoReference reference)const{validate();require(owner_->config.stereo_schedule==DaxaDepthStereoSchedule::SharedCensusSequential,"independent producer leases require shared Census aligned admission");require(reference==DaxaStereoReference::Left||reference==DaxaStereoReference::Right,"unknown stereo reference");return reference==DaxaStereoReference::Left?slot_->left:slot_->right;}
DaxaDepthTiming DaxaDepthPipeline::Frame::timings()const{validate();owner_->require_thread();require(ready(),"depth completion required before timing");std::array<uint64_t,8> result{};require(daxa_timeline_query_pool_query_results(slot_->queries.get(),0,4,result.data())==DAXA_RESULT_SUCCESS,"depth timestamp query failed");for(unsigned i=0;i<4;++i)require(result[i*2+1],"depth timestamp unavailable");auto mask=owner_->timestamp_bits==64?UINT64_MAX:(uint64_t{1}<<owner_->timestamp_bits)-1;auto ms=[&](unsigned a,unsigned b){return double((result[b*2]-result[a*2])&mask)*owner_->timestamp_period/1e6;};DaxaDepthTiming out;out.preprocessing_timings_available=bool(owner_->preprocessing);out.combined_gpu_timing_available=out.preprocessing_timings_available;if(owner_->preprocessing)out.preprocessing=owner_->preprocessing->timings(slot_->preprocessing);else{auto unavailable=std::numeric_limits<double>::quiet_NaN();out.preprocessing.upload_ms=out.preprocessing.decode_ms=out.preprocessing.rectify_ms=out.preprocessing.total_ms=unavailable;out.combined_gpu_ms=unavailable;}if(owner_->config.stereo_schedule!=DaxaDepthStereoSchedule::Sequential){out.per_reference_stereo_timings_available=false;out.paired_stereo=owner_->left->pair_timings(slot_->left,slot_->right);}else{out.left=slot_->left.timings();out.right=slot_->right.timings();}out.lr_gpu_ms=ms(0,1);out.metric_metadata_gpu_ms=ms(2,3);auto& stereo=out.per_reference_stereo_timings_available?out.left:out.paired_stereo;require(stereo.timestamp_bits==owner_->timestamp_bits&&stereo.timestamp_period==double(owner_->timestamp_period),"stereo-to-metric timestamp properties differ");if(out.preprocessing_timings_available)require(out.preprocessing.timestamp_bits==owner_->timestamp_bits&&out.preprocessing.timestamp_period==double(owner_->timestamp_period),"combined timestamp properties differ");long double wrap_ns=std::ldexp(static_cast<long double>(owner_->timestamp_period),int(owner_->timestamp_bits));auto elapsed_ns=std::chrono::duration<long double,std::nano>(std::chrono::steady_clock::now()-slot_->host_start).count();require(elapsed_ns<wrap_ns,"combined timestamp wrap interval ambiguous");out.stereo_to_metric_gpu_ms=double((result[6]-stereo.start_tick)&mask)*owner_->timestamp_period/1e6;if(out.combined_gpu_timing_available)out.combined_gpu_ms=double((result[6]-out.preprocessing.start_tick)&mask)*owner_->timestamp_period/1e6;return out;}
DaxaDepthReadback DaxaDepthPipeline::readback(const Frame& frame)const{frame.validate();impl_->require_thread();require(frame.owner_==impl_,"foreign depth readback");frame.wait();auto& d=impl_->context->device;DaxaDepthReadback out;out.right_reference_mode=frame.right_reference_mode();out.lr_dependency=frame.lr_dependency();
    auto copy=[&](auto& values,unsigned p){size_t bytes=frame.size_bytes(DaxaDepthPlane(p));daxa::BufferInfo info{.size=bytes,.name="scoped depth diagnostic"};auto memory=d.create_memory({.requirements=impl_->context->coherent_readback_requirements(info),.flags=daxa::MemoryFlagBits::HOST_ACCESS_RANDOM});auto host=d.create_buffer_from_memory_block({.buffer_info=info,.memory_block=memory});struct Cleanup{daxa::Device& d;daxa::BufferId b;~Cleanup(){d.destroy_buffer(b);d.collect_garbage();}}cleanup{d,host};auto recorder=d.create_command_recorder({.name="depth diagnostic readback"});recorder.pipeline_barrier({.src_access=daxa::AccessConsts::COMPUTE_SHADER_WRITE,.dst_access=daxa::AccessConsts::TRANSFER_READ});recorder.copy_buffer_to_buffer({.src_buffer=frame.slot_->outputs[p],.dst_buffer=host,.size=bytes});recorder.pipeline_barrier({.src_access=daxa::AccessConsts::TRANSFER_WRITE,.dst_access=daxa::AccessConsts::HOST_READ});auto command=recorder.complete_current_commands();d.submit_commands({.command_lists={&command,1}});d.wait_idle();values.resize(bytes/sizeof(typename std::remove_reference_t<decltype(values)>::value_type));std::memcpy(values.data(),d.buffer_host_address(host).value(),bytes);};
    copy(out.lr_disparity,0);copy(out.lr_confidence,1);copy(out.lr_validity,2);copy(out.depth,3);copy(out.metric_confidence,4);copy(out.metric_validity,5);copy(out.provenance,6);copy(out.source_ids,7);copy(out.age_ns,8);return out;}
DaxaPreprocessReadback DaxaDepthPipeline::readback_images(const Frame& f)const{f.validate();require(f.owner_==impl_,"foreign depth RGB readback");require(bool(impl_->preprocessing),"external depth images require producer diagnostic readback");return impl_->preprocessing->readback(f.slot_->preprocessing);}
DaxaDepthStereoInput DaxaDepthPipeline::readback_stereo(const Frame& f)const{f.validate();require(f.owner_==impl_,"foreign depth stereo readback");require(bool(impl_->preprocessing),"external depth combined stereo/support readback requires producer diagnostics");auto l=impl_->left->readback(f.slot_->left),r=impl_->right->readback(f.slot_->right);auto images=readback_images(f);DaxaDepthStereoInput out;out.disparity={std::move(l.disparity),std::move(r.disparity)};out.confidence={std::move(l.confidence),std::move(r.confidence)};out.validity={std::move(l.validity),std::move(r.validity)};out.support={std::move(images.planes[6]),std::move(images.planes[7])};return out;}
DaxaStereoReadback DaxaDepthPipeline::readback_stereo(const Frame& f,DaxaStereoReference reference,bool intermediate)const{f.validate();require(f.owner_==impl_,"foreign depth stereo diagnostic");require(reference==DaxaStereoReference::Left||reference==DaxaStereoReference::Right,"unknown diagnostic reference");return reference==DaxaStereoReference::Left?impl_->left->readback(f.slot_->left,intermediate):impl_->right->readback(f.slot_->right,intermediate);}
void DaxaDepthPipeline::check_stereo_integer(const Frame& f,const DaxaPreprocessReadback& images)const{f.validate();require(f.owner_==impl_,"foreign stereo diagnostic frame");require(impl_->config.right_reference_mode==DaxaRightReferenceMode::IndependentSGM,"legacy integer diagnostic requires independent Right SGM");for(unsigned eye=0;eye<2;++eye){auto& engine=eye?*impl_->right:*impl_->left;auto actual=engine.readback(eye?f.slot_->right:f.slot_->left,true);auto scalar=daxa_stereo_reference(impl_->config.stereo,images.planes[4],images.planes[5],std::nullopt,eye?DaxaStereoReference::Right:DaxaStereoReference::Left);require(actual.census==scalar.census&&actual.census_valid==scalar.census_valid&&actual.costs==scalar.costs&&actual.sums==scalar.sums&&actual.validity==scalar.validity,"dual stereo independent integer/Census/mask mismatch");auto bits=engine.packing_bits(),components=32/bits,words=(impl_->config.stereo.disparities+components-1)/components;size_t n=size_t(impl_->config.stereo.width)*impl_->config.stereo.height;std::vector<uint32_t> packed(n*words);for(size_t i=0;i<n;++i)for(unsigned d=0;d<impl_->config.stereo.disparities;++d){auto index=i*impl_->config.stereo.disparities+d;auto base=impl_->config.stereo.paths*scalar.costs[index];require(scalar.sums[index]>=base&&scalar.sums[index]-base<=impl_->config.stereo.paths*impl_->config.stereo.p2,"scalar residual outside packed bound");packed[i*words+d/components]|=(scalar.sums[index]-base)<<((d%components)*bits);}require(actual.packed_penalties==packed,"actual dual-reference GPU packed words differ from independently packed scalar residuals");}}
void DaxaDepthPipeline::check_derived_stereo_integer(const Frame& f,const DaxaPreprocessReadback& images)const{
    f.validate();require(f.owner_==impl_&&f.right_reference_mode()==DaxaRightReferenceMode::LeftAggregatedSelection,"derived diagnostic requires derived owner");
    auto c=impl_->config.stereo;auto left=impl_->left->readback(f.slot_->left,true);auto scalar=daxa_stereo_reference(c,images.planes[4],images.planes[5]);
    require(left.census==scalar.census&&left.census_valid==scalar.census_valid&&left.costs==scalar.costs&&left.sums==scalar.sums&&left.validity==scalar.validity,"derived Left integer/Census/mask mismatch");
    auto bits=left.packing_bits,components=32/bits,words=(c.disparities+components-1)/components;size_t n=size_t(c.width)*c.height;std::vector<uint32_t> packed(n*words);
    for(size_t i=0;i<n;++i)for(unsigned d=0;d<c.disparities;++d){auto index=i*c.disparities+d;auto base=c.paths*scalar.costs[index];require(scalar.sums[index]>=base&&scalar.sums[index]-base<=c.paths*c.p2,"derived Left residual bound");packed[i*words+d/components]|=(scalar.sums[index]-base)<<((d%components)*bits);}
    require(left.packed_penalties==packed,"derived actual Left P differs from independently packed scalar residuals");
    auto right=impl_->right->readback(f.slot_->right,false);auto derived=daxa_left_aggregated_selection_reference(c,scalar);require(right.validity==derived.validity,"derived Right mask differs from independent scalar Left-sum selection");
    require(left.estimator==DaxaStereoEstimator::IndependentSGM&&right.estimator==DaxaStereoEstimator::LeftAggregatedSelection&&left.right_reference_mode==right.right_reference_mode&&f.lr_dependency()==DaxaLRDependency::LeftAggregatedCorrelated,"derived typed estimator/dependency metadata");
    auto input=readback_stereo(f);auto expected=daxa_depth_reference(impl_->config,f.metric_calibration(),input,f.source()->frame_id);auto actual=readback(f);
    require(actual.lr_validity==expected.lr_validity&&actual.metric_validity==expected.metric_validity&&actual.provenance==expected.provenance&&actual.source_ids==expected.source_ids&&actual.age_ns==expected.age_ns&&actual.lr_dependency==expected.lr_dependency&&actual.right_reference_mode==expected.right_reference_mode,"derived LR/provenance metadata mismatch");
}
uint64_t DaxaDepthPipeline::completed_output_retirements()const{return impl_->retired;}uint64_t DaxaDepthPipeline::requested_observation_bytes()const{return impl_->allocated;}uint64_t DaxaDepthPipeline::requested_combined_buffer_bytes()const{return impl_->combined_allocated;}double DaxaDepthPipeline::last_upload_cpu_ms()const{require(bool(impl_->preprocessing),"external depth has no owned producer upload timing");return impl_->preprocessing->last_upload_cpu_ms();}
std::string DaxaDepthPipeline::derived_shader_identity(){return std::string(SF_DAXA_DEPTH_DERIVED_SHA256)+":"+SF_DAXA_DEPTH_WRAPPER_SHA256+":"+SF_DAXA_DEPTH_OPS_SHA256;}
std::string DaxaDepthPipeline::shader_directory(){return SF_DAXA_DEPTH_SPIRV_DIRECTORY;}std::string DaxaDepthPipeline::shader_identity(){return std::string(SF_DAXA_DEPTH_WRAPPER_SHA256)+":"+SF_DAXA_DEPTH_OPS_SHA256;}
